   // Non-A bands use intervals learned from prior manual grades, never a race average.
   const gap=Number.isFinite(e.margin)?e.margin-boundary:(e.relatives[0]?.value??-Infinity)-98,bands=calibration?.lowerBands??{bplus:-2,b:-5,cplus:-9,c:-14};
