  const benchmark=target.months[month(c.date)]?.median??target.median;
  const adjust=r=>{
   const ref=season[`${r[4]}|${c.surface}`];
   // Population clock seasonality, not a promised growth bonus for this horse.
   return ref?Math.max(-3,Math.min(3,(ref.months[month(c.date)]?.median??ref.median)-(ref.months[month(r[0])]?.median??ref.median))):0;
  };
