  if(f.upperRelative.length){if(order.indexOf(rank)<order.indexOf('A'))rank='A';reasons.push('近条件の上級補正98以上を直接根拠');}
  if(upperProof){if(order.indexOf(rank)<order.indexOf('A'))rank='A';reasons.push(`上級${upperProof[4]>=7?'重賞':'OP'}${upperProof[10]}着・補正${upperProof[6]}・補9${upperProof[7]}をA以上の根拠`);}
  if(lowerProof){if(order.indexOf(rank)<order.indexOf('A'))rank='A';reasons.push(`下級勝利の高補正${lowerProof[6]}・補9${lowerProof[7]}を昇級根拠`);}
